require "db.php";$id=(int)($_GET["id"]??0);if($id<1)exit("Bill ID required.");
$q=$conn->prepare("SELECT b.*,f.name farmer_name,f.phone,f.address FROM bills b JOIN farmers f ON f.id=b.farmer_id WHERE b.id=?");$q->bind_param("i",$id);$q->execute();$bill=$q->get_result()->fetch_assoc();if(!$bill)exit("Bill not found.");
$wq=$conn->prepare("SELECT weight_no,weight FROM bill_weights WHERE bill_id=? ORDER BY weight_no");$wq->bind_param("i",$id);$wq->execute();$weights=$wq->get_result();
$pq=$conn->prepare("SELECT amount,payment_date,note FROM bill_payments WHERE bill_id=? ORDER BY payment_date DESC,id DESC");$pq->bind_param("i",$id);$pq->execute();$payments=$pq->get_result();
$sq=$conn->prepare("SELECT COALESCE(SUM(amount),0) paid FROM bill_payments WHERE bill_id=?");$sq->bind_param("i",$id);$sq->execute();$extra=(float)$sq->get_result()->fetch_assoc()["paid"];
$paid=(float)$bill["paid_amount"]+$extra;$due=max(0,round((float)$bill["previous_balance"]+(float)$bill["total_amount"]-$paid,2));
$phone=preg_replace('/[^0-9]/','',(string)$bill["phone"]);if(str_starts_with($phone,"0"))$phone="94".substr($phone,1);elseif($phone!==""&&!str_starts_with($phone,"94"))$phone="94".$phone;
$msg="JM PADDY Bill ".$bill["bill_no"]."\nFarmer: ".$bill["farmer_name"]."\nDate: ".$bill["bill_date"]."\nNet Weight: ".number_format((float)$bill["net_weight"],2)." kg\nBill Amount: Rs. ".number_format((float)$bill["total_amount"],2)."\nPrevious Balance: Rs. ".number_format((float)$bill["previous_balance"],2)."\nPaid: Rs. ".number_format($paid,2)."\nBalance Due: Rs. ".number_format($due,2);$wa="https://wa.me/".$phone."?text=".rawurlencode($msg);
