<h3 class="screen-only">Weight Details</h3><div class="weight-details" style="overflow-x:auto"><?php $weightRows=[];while($x=$weights->fetch_assoc()){$weightRows[]=$x;} ?><table><thead><tr><?php for($i=0;$i<5;$i++): ?><th>No.</th><th>Weight kg</th><?php endfor; ?></tr></thead><tbody><?php if(!$weightRows): ?><tr><td colspan="10">No weight details.</td></tr><?php else: for($i=0;$i<count($weightRows);$i+=5): ?><tr><?php for($j=0;$j<5;$j++): $x=$weightRows[$i+$j]??null; ?><td><?= $x?(int)$x["weight_no"]:"" ?></td><td><?= $x?number_format((float)$x["weight"],2):"" ?></td><?php endfor; ?></tr><?php endfor; endif; ?></tbody></table></div><div class="print-summary" style="display:none"><b>Weight summary:</b> Gross <?= number_format((float)$bill["total_weight"],2) ?> kg &nbsp; · &nbsp; Divisor <?= number_format((float)$bill["district_rate"],2) ?> &nbsp; · &nbsp; Net <?= number_format((float)$bill["net_weight"],2) ?> kg</div>
